def replay(commands):
    figures = []
    open_order = []
    current_fig = None
    current_ax = None
    for cmd in commands:
        kind = cmd[0]
        if kind == "figure":
            n = cmd[1]
            figures.append([[] for _ in range(n)])
            index = len(figures) - 1
            open_order.append(index)
            current_fig = index
            current_ax = 0 if n else None
        elif kind == "select":
            _, fig, ax = cmd
            if fig not in open_order:
                raise ValueError(f"figure {fig} is not open")
            if not 0 <= ax < len(figures[fig]):
                raise ValueError(f"figure {fig} has no axes {ax}")
            current_fig = fig
            current_ax = ax
        elif kind == "plot":
            if current_fig is None:
                figures.append([[]])
                current_fig = len(figures) - 1
                open_order.append(current_fig)
                current_ax = 0
            elif current_ax is None:
                figures[current_fig].append([])
                current_ax = len(figures[current_fig]) - 1
            figures[current_fig][current_ax].append(cmd[1])
        elif kind == "close":
            if current_fig is None:
                raise ValueError("no figure to close")
            open_order.remove(current_fig)
            if open_order:
                current_fig = open_order[-1]
                current_ax = 0 if figures[current_fig] else None
            else:
                current_fig = None
                current_ax = None
        else:
            raise ValueError(f"unknown command {kind!r}")
    return figures
